pub fn solve() {
    let now = std::time::Instant::now();
    crate::prepare!(?);
    scln!(n, m, l: i64, u: i64);
    assert_eq!(n, N);
    assert_eq!(m, M);
    assert_eq!(l, L);
    assert_eq!(u, U);
    const D: usize = 100;
    let mut rng = Xorshift::default();
    let bs: Vec<Vec<i64>> = (0..30000)
        .map(|_| {
            let mut b: Vec<_> = rng.random_iter(L..=U).take(M).collect();
            b.sort_unstable();
            b
        })
        .collect();
    let bl: Vec<_> = (0..M)
        .map(|j| (0..bs.len()).map(|i| bs[i][j]).min().unwrap())
        .collect();
    let f = |seeds: &[f64]| {
        let mut a = vec![1i64; N];
        let mut p = 0;
        for _ in 0..M {
            a[p] = bl[p];
            p += 1;
        }
        let mut d = (U - L) as f64;
        for i in M..N {
            d *= seeds[((i - M) / D).min(seeds.len() - 1)];
            a[p] = (d as i64).clamp(1, U);
            p += 1;
            if p >= N {
                break;
            }
        }
        a.sort_unstable();
        a.reverse();
        a
    };
    #[rustfmt::skip]
    let mut seeds = vec![0.9519737781942561, 0.9522647943960307, 0.9519794088740399, 0.9507103666247043];
    // let mut seeds = vec![0.96f64; (N - M) / D];
    if false {
        for _ in 0..1 {
            for i in 0..seeds.len() {
                eprintln!("i = {:?}", i);
                let (x, _) = ternary_search(0.9..=1.0, |x| {
                    for j in i..seeds.len() {
                        seeds[j] = x;
                    }
                    -test(f(&seeds))
                });
                for j in i..seeds.len() {
                    seeds[j] = x;
                }
            }
            eprintln!("seeds = {:?}", seeds);
        }
    }
    let a = f(&seeds);
    pp!(@it &a; @flush);
    scln!(b: [i64; M]);
    let (_, x) = calc(a, b);
    pp!(@it x.iter().map(|&x| x.wrapping_add(1)); @flush);
    eprintln!("elapsed = {:?}", now.elapsed());
}
pub fn calc(a: Vec<i64>, b: Vec<i64>) -> (i64, Vec<usize>) {
    let f = |d: i64| {
        let mut b = b.clone();
        let mut heap = BinaryHeap::new();
        for i in 0..M {
            b[i] += d;
        }
        for i in 0..M {
            heap.push((Reverse(b[i]), i));
        }
        let mut x = vec![!0; N];
        while let Some((Reverse(_), j)) = heap.pop() {
            for i in 0..N {
                if x[i] == !0 && b[j] >= a[i] {
                    x[i] = j;
                    b[j] -= a[i];
                    heap.push((Reverse(b[j]), j));
                    break;
                }
            }
        }
        let mut s = 0i64;
        for i in 0..M {
            s += (b[i] - d).abs();
        }
        (s, x)
    };
    let d = ternary_search(0..=500, |d| f(d).0).0;
    let (s, x) = f(d);
    (s, x)
}
#[cfg(not(feature = "local"))]
pub fn test(_a: Vec<i64>) -> i64 {
    0
}
#[cfg(feature = "local")]
pub fn test(a: Vec<i64>) -> i64 {
    use rayon::prelude::*;
    let mut rng = Xorshift::default();
    let bs: Vec<Vec<i64>> = (0..10000)
        .map(|_| rng.random_iter(L..=U).take(M).collect())
        .collect();
    let score: i64 = bs
        .into_par_iter()
        .map(|b| {
            let (s, _) = calc(a.clone(), b);
            ((20. - (1. + s as f64).log10()) * 5e7).round() as i64
        })
        .sum();
    score
}
const N: usize = 500;
const M: usize = 50;
const L: i64 = 1_000_000_000_000_000 - 2_000_000_000_000;
const U: i64 = 1_000_000_000_000_000 + 2_000_000_000_000;
crate::main!();
